class GymMember{private static int counter=2000,membersEnrolled=0;private final String membershipNumber;private int monthlyFee,feesPaid;private String paymentMode="Not specified";public GymMember(int fee){if(fee<=0)throw new IllegalArgumentException("Fee must be positive");monthlyFee=fee;counter++;membershipNumber="GYM-"+counter;membersEnrolled++;}public String getMembershipNumber(){return membershipNumber;}public void payFee(int n){if(n>0)feesPaid+=n;}public void payFee(int n,String mode){paymentMode=mode;payFee(n);}public int getFeesPaid(){return feesPaid;}public String getPaymentMode(){return paymentMode;}public static int getMembersEnrolled(){return membersEnrolled;}public static boolean isValidReferralCode(String c){return c!=null&&c.length()==4&&c.charAt(0)=='G'&&Character.isDigit(c.charAt(1))&&Character.isDigit(c.charAt(2))&&Character.isUpperCase(c.charAt(3))&&Character.isLetter(c.charAt(3));}}
class GroupClassMember extends GymMember{private String className;public GroupClassMember(int fee,String c){super(fee);className=c;}public String getClassName(){return className;}}
public class WeeklyCheckInSettlement{static String processWeeklyCheckIn(GymMember[] a){int p=0,n=0,g=0,i=0;for(GymMember m:a){if(m==null){n++;continue;}p++;if(m instanceof GroupClassMember)g++;else i++;}return p+" processed | "+n+" null skipped | "+g+" group | "+i+" individual";}public static void main(String[] args){GymMember m=new GymMember(1000);System.out.println(m.getMembershipNumber());System.out.println(GymMember.getMembersEnrolled());System.out.println(GymMember.isValidReferralCode("G45B"));System.out.println(GymMember.isValidReferralCode("G4B"));System.out.println(GymMember.isValidReferralCode("X45B"));m.payFee(500);m.payFee(500,"UPI");System.out.println(m.getFeesPaid());System.out.println(m.getPaymentMode());System.out.println(processWeeklyCheckIn(new GymMember[]{new GroupClassMember(1500,"Zumba"),null,new GymMember(1000)}));}}